@router.patch({{path}}, response_model=ParentRead)
def patch_parent(parent_id: int, data: ParentPatch, db: Annotated[Session, Depends(session_provider)]) -> Parent:
    """Patch parent."""
    row = require_parent(db, parent_id)
    for name, value in model_values(data, exclude_unset=True).items():
        setattr(row, name, value)
    try:
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc)
    db.refresh(row)
    return row
